import { startTestBackend } from '@fasrun/test-utils';
import { describe, expect, it } from 'vitest';
import { connectPlugin } from './plugin.js';

describe('connect plugin', () => {
  it('serves its status under /api/connect/v1', async () => {
    const backend = await startTestBackend({ features: [connectPlugin] });
    try {
      const response = await backend.server.inject({ method: 'GET', url: '/api/connect/v1/status' });
      expect(response.json()).toEqual({ plugin: 'connect', status: 'ok' });
    } finally {
      await backend.stop();
    }
  });
});

// Assembly only (tech plan 2.1): wires the services the plugin needs to its application layer.
import { coreServices, createBackendPlugin } from '@fasrun/backend-plugin-api';
import { getStatus } from '../application/status.js';

export const connectPlugin = createBackendPlugin({
  pluginId: 'connect',
  register(env) {
    env.registerInit({
      deps: { logger: coreServices.logger, router: coreServices.httpRouter },
      init({ logger, router }) {
        router.use((app) => {
          app.get('/status', (_request, reply) => reply.send(getStatus()));
          return Promise.resolve();
        });
        logger.info('connect plugin initialised');
      },
    });
  },
});

